import{af as n,ad as r,z as s,J as c,K as a,y as t,x as o,ab as h}from"./chunks/framework.D-2fLa7v.js";const _=JSON.parse('{"title":"Pro","description":"","frontmatter":{"aside":true},"headers":[],"relativePath":"devices/pro/index.md","filePath":"devices/pro/index.md"}'),l={name:"devices/pro/index.md"},p={class:"pro-overview"},f={class:"pro-overview__layout"},g={class:"pro-overview__copy"};function v(u,e,P,b,m,y){const i=r("DeviceCapabilities"),d=r("ProImageGallery");return s(),c("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1794240761000"},[e[3]||(e[3]=a("h1",{id:"pro",tabindex:"-1"},[t("Pro "),a("a",{class:"header-anchor",href:"#pro","aria-label":'Permalink to "Pro"'},"​")],-1)),a("div",p,[a("div",f,[a("div",g,[e[0]||(e[0]=a("p",null,[t("The current Pro is Pro3 (PR3), a different hardware generation from "),a("a",{href:"/docs/pr/40/devices/history/PR2"},"ProN (PR2)"),t(". The two generations share the same external appearance, so use the product code and hardware revision to identify your device before following its instructions. ProN (PR2) is now a legacy model and is no longer in production.")],-1)),e[1]||(e[1]=a("h2",{id:"capabilities",tabindex:"-1"},[t("Feature guides "),a("a",{class:"header-anchor",href:"#capabilities","aria-label":'Permalink to "Feature guides {#capabilities}"'},"​")],-1)),o(i,{device:"PR3"}),e[2]||(e[2]=a("p",null,[t("Pro3 does not have the separate "),a("a",{href:"/docs/pr/40/devices/capabilities/gps-gsm-status-leds"},"GPS and GSM status LEDs"),t(" used by the older ProN/PR2. Use the product code and revision, not the enclosure appearance, to choose the matching documentation.")],-1))]),o(d)])]),e[4]||(e[4]=h('<h2 id="hardware-generations" tabindex="-1" data-v-d066110f>Hardware generations <a class="header-anchor" href="#hardware-generations" aria-label="Permalink to &quot;Hardware generations&quot;" data-v-d066110f>​</a></h2><table tabindex="0" data-v-d066110f><thead data-v-d066110f><tr data-v-d066110f><th data-v-d066110f>Generation</th><th data-v-d066110f>LED layout</th><th data-v-d066110f>Documentation</th></tr></thead><tbody data-v-d066110f><tr data-v-d066110f><td data-v-d066110f>Pro3 / PR3 (current)</td><td data-v-d066110f>Four orange indicators on revisions 02–04</td><td data-v-d066110f>This page</td></tr><tr data-v-d066110f><td data-v-d066110f>ProN / PR2 (legacy)</td><td data-v-d066110f>Four battery indicators plus two diagnostic indicators</td><td data-v-d066110f><a href="/docs/pr/40/devices/history/PR2" data-v-d066110f>PR2 archive</a></td></tr></tbody></table><p data-v-d066110f>This is a generation guide, not a complete Pro3 specification. Cellular bands, wireless features, charging limits and certifications must be checked for the supplied Pro3 revision. The <a href="/docs/pr/40/devices/history/PR2" data-v-d066110f>PR2 specification download</a> applies to PR2 only.</p><h2 id="led-indicators" tabindex="-1" data-v-d066110f>LED indicators <a class="header-anchor" href="#led-indicators" aria-label="Permalink to &quot;LED indicators&quot;" data-v-d066110f>​</a></h2><p data-v-d066110f>The <a href="/docs/pr/40/devices/capabilities/four-power-leds" data-v-d066110f>four power LED capability</a> defines the normal battery and charging patterns. On revisions 02–04 these indicators are orange. They are also used during startup and for alerts, so four lit indicators are not always a battery reading.</p><p data-v-d066110f>There is no separate GPS/mobile-network colour table on Pro3. The older <a href="/docs/pr/40/devices/history/PR2#two-red-lights-and-four-orange-lights-after-a-restart" data-v-d066110f>PR2 example of two red and four orange lights</a> is not this model’s layout. Use the <a href="/docs/pr/40/guides/leds" data-v-d066110f>LED guide</a> for the first checks when a pattern is unfamiliar.</p><h3 id="charger-protection" tabindex="-1" data-v-d066110f>Charger protection <a class="header-anchor" href="#charger-protection" aria-label="Permalink to &quot;Charger protection&quot;" data-v-d066110f>​</a></h3><p data-v-d066110f>The charger can trigger a protection pattern that differs from the normal charging blink. If two lights keep flashing together or charging does not progress, contact <a href="https://lightbug.io/contact/" target="_blank" rel="noreferrer" data-v-d066110f>support</a> with a video and details of the charging accessory. Do not treat every flashing pattern as a battery reading.</p><h2 id="charging" tabindex="-1" data-v-d066110f>Charging <a class="header-anchor" href="#charging" aria-label="Permalink to &quot;Charging&quot;" data-v-d066110f>​</a></h2><p data-v-d066110f>Use the charging accessory and power supply specified for your Pro3 revision. Do not apply PR2 voltage/current ratings or charging-time instructions to Pro3.</p><p data-v-d066110f>See <a href="/docs/pr/40/devices/capabilities/four-power-leds#charging" data-v-d066110f>four power LED charging patterns</a> for the normal blinking and steady states. A steady high-charge display is not an exact 100% reading.</p><h2 id="pro-pr2" tabindex="-1" data-v-d066110f>Earlier Pro generations <a class="header-anchor" href="#pro-pr2" aria-label="Permalink to &quot;Earlier Pro generations {#pro-pr2}&quot;" data-v-d066110f>​</a></h2><p data-v-d066110f>The <a href="/docs/pr/40/devices/history/PR2" data-v-d066110f>ProN/PR2 archive</a> contains its specifications, images and diagnostic-light information. PR2 is no longer in production.</p><h2 id="get-help" tabindex="-1" data-v-d066110f>Get help <a class="header-anchor" href="#get-help" aria-label="Permalink to &quot;Get help&quot;" data-v-d066110f>​</a></h2><p data-v-d066110f>For specifications or troubleshooting, <a href="https://lightbug.io/contact/" target="_blank" rel="noreferrer" data-v-d066110f>contact support</a> with the product code, device ID and hardware revision if known. Include whether the device is charging and a short video if you are asking about a repeating light pattern.</p>',15))])}const x=n(l,[["render",v],["__scopeId","data-v-d066110f"]]);export{_ as __pageData,x as default};
